import styled from "styled-components";

export const DetailWrapper= styled.div`
    width:100%;
    margin-top:2rem;
    
    h3{
        font-family: "Nunito Sans", "Helvetica Neue", HelveticaNeue, Helvetica, Arial, sans-serif;
        color:rgb(74, 74, 74);
       
        
        
    }

    
`
export const TitleContainer = styled.div`
    width: 100%;
    display: flex;
    justify-content: center;
    align-items: center;
    text-align: center;

    h1{
        font-family: "Raleway", sans serif;
        color:rgb(74, 74, 74);
        
    }  
    `
    export const ImageContainer = styled.div`
    width: 100%; 
    margin-top: 1rem;
    display: flex;
    flex-direction: column;
    border: 1px solid rgba(0,0,0,0.15);
    border-radius: 10px;
    margin-bottom:20px;

    `

export const DetailsContainer = styled.div`
width: 100%;
margin-top: 1rem;



    h2{
        font-family: "Nunito Sans", "Helvetica Neue", HelveticaNeue, Helvetica, Arial, sans-serif;
        color:rgb(74, 74, 74);
        font-weight:600;
        font-size:2rem;
    }
    p{
     
            font-family: "Nunito Sans", "Helvetica Neue", HelveticaNeue, Helvetica, Arial, sans-serif;
            color:rgb(74, 74, 74);
        
    }
   
`




export const Detailgrid= styled.div`
    width:100%;
    display: grid;
    grid-template-columns: repeat(16, 1fr);
    grid-template-rows: repeat(2, 3rem);

    div{
        margin-top:1rem;
       
    }
    div>h4{
        font-family: "Nunito Sans", "Helvetica Neue", HelveticaNeue, Helvetica, Arial, sans-serif;
        color: #b0b0ad;
        font-weight: 400;
        font-size: 1rem;
        
    }
    div>span{
        font-family: "Nunito Sans", "Helvetica Neue", HelveticaNeue, Helvetica, Arial, sans-serif;
        font-weight: 600;
        color:rgb(74, 74, 74);
    }
 
    div:nth-child(1){
        grid-column: 1/4;
        grid-row: 1/3;
        

    }
    div:nth-child(2){
        grid-column: 5/8;
        grid-row: 1/3;

    }
    div:nth-child(3){
        grid-column: 9/13;
        grid-row: 1/3;

    }
    div:nth-child(4){
        grid-column: 13/16;
        grid-row: 1/3;

    }
    
 
    
`

export const LandImageContainer=styled.div`
    width: 100%;
    height: 100%;
`
export const LandImageItemContainer=styled.div`
    width: 100%;
    height: 100%;
    display: flex;
    flex-direction:column;
    
    
`

export const LandImageContainerVW=styled.div`
    width: 100%;
    height: 100%;
    position: relative;

    img{
        width:100%;
        height:100%;
        object-fit: cover;
        border-radius: 10px;
    }
    
    arrow{
        position: absolute; 
        top:10px;
        left:0;
       
    }
`
export const LandImageContainerVH=styled.div`
    width: 100%;
    height: 100%;
    box-sizing: border-box;
    display: flex;
    
    align-items: center;
    justify-content: space-around;
    padding:5px;

    div{
        display: flex;
        align-items: center;
        flex-direction: column;
        justify-content: space-around;
        width:50%;
        height:50px;
        object-fit: cover;
        
    }
    img{
        width:100%;
        height:100%;
        object-fit: cover;
        border-radius: 5px;
        
    }

`


export const DetailLocalizationWrapper= styled.div`
    width:100%;
    margin-top:2rem;
    
    h3{
        font-family: "Nunito Sans", "Helvetica Neue", HelveticaNeue, Helvetica, Arial, sans-serif;
        color:rgb(74, 74, 74);
        
    }

    
`
export const DetailLocalizationgrid= styled.div`
    width:100%;
    display: grid;
    grid-template-columns: repeat(16, 1fr);
    grid-template-rows: repeat(2, 3rem);

    div{
        margin-top:1rem;
    }
    .divLocalization>h4{
        font-family: "Nunito Sans", "Helvetica Neue", HelveticaNeue, Helvetica, Arial, sans-serif;
        color: #b0b0ad;
        font-weight: 400;
        font-size: 1rem;
    }
    .divLocalization>span{
        font-family: "Nunito Sans", "Helvetica Neue", HelveticaNeue, Helvetica, Arial, sans-serif;
        font-weight: 600;
        color:rgb(74, 74, 74);
    }
 
    .divLocalization:nth-child(1){
        grid-column: 1/4;
        grid-row: 1/3;
        

    }
    .divLocalization:nth-child(2){
        grid-column: 5/8;
        grid-row: 1/3;

    }
    .divLocalization:nth-child(3){
        grid-column: 9/13;
        grid-row: 1/3;

    }
    .divLocalization:nth-child(4){
        grid-column: 13/16;
        grid-row: 1/3;

    }
    
 
    
`
